import * as React from 'react'
import { useMutation, useQuery } from 'react-query'
import { z } from 'zod'
import axios from 'axios';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import toast from 'react-hot-toast';
import { Chess } from 'chess.js'
import chessImageUrl from 'chess-image-url';
import { Chessboard } from 'chess.js graphics'
import '../App.css'

const textSchema = z.object({
  text: z.object({
    user: z.string(),
    steamId64: z.string(),
    text: z.string(),
  }),
})

type TextSchema = z.infer<typeof textSchema>

const StateGenerator = (props: { gameId: string }) => {
  const chess = new Chess();
  const [page, setPage] = React.useState<number>(1);
  const [moves, setMoves] = React.useState<string[]>([]);
  const [gameResult, setGameResult] = React.useState<string>('');
  const [fsName, setFsName] = React.useState<string>('');

  const mutation = useMutation<void, { err: string }, TextSchema>(async (userInput) => {
    return axios.post('/api/generate-game-score', userInput).then(response => {
      return response.data;
    })
  }, {
    onSuccess: () => toast.success('Game score generated!'),
    onError: err => toast.error(err),
  })

  const form = useForm<TextSchema>({
    resolver: zodResolver(textSchema),
  });

  return <div className='flex flex-col space-y-2'>
    <div className='text-xl font-bold'>Game {page}</div>
    <div className='grid grid-cols-3 gap-2'>
      <div className='w-full bg-black p-2'>
        <Chessboard className="min-w-[400px]" position={chess.fen()} />
      </div>
      <div className='w-full bg-white p-2'>
        {gameResult === '' ? <p className='text-gray-800 text-xl font-extrabold italic'>Enter player names and steam id 64 to generate report</p> : <pre className='text-gray-800 text-xl font-extrabold italic'>{gameResult}</pre>}
      </div>
      <article className='w-full bg-white p-2'>
        <form className="flex w-full flex-col space-y-2"
          onSubmit={s => {
            mutation.mutate(form.setValue({
              text: {
                user: s.target.name.value,
                steamId64: s.target.id.value,
                text: s.target.fs_name.value
              }
            }))(s); return false;
          }}
        >
          <div className="flex w-full space-x-4">
            {page === 1 ? <input name="player1" type="text" className="input" /> : null}
            {page === 2 ? <input name="player2" type="text" className="input" /> : null}
          </div>
          <div className="flex w-full items-stretch space-x-4">
            {page === 1 ? <input name="fsName" type="text" className="input w-[400px]" /> : ' '}
            {page === 2 ? <input defaultValue={moves.join('; ').substring(2)} type="text" className="input w-[400px]" readOnly /> : null}
            {page === 1 || page === 2 ? <input type="submit" className="py-2 text-white bg-stop-watching transition-colors duration-300 relative overflow-hidden" /> : null}
            {page === 2 ? <input name="id" type="hidden" className="input w-[400px]" defaultValue={props.gameId} /> : null}
          </div>
          <div>
            {page === 1 ? <button type="button" onClick={ () => { setPage(2); } } className="p-1 bg-red-400 hover:bg-red-500">Continue</button> : null}
            {page === 2 ? <button type="button" onClick={ () => { setPage(1); } } className="p-1 bg-red-400 hover:bg-red-500">Previous</button> : null}
          </div>
        </form>
      </article>
    </div>
  </div>
}

